module schedule_optimizer (input clk, input rst_n, input start, input [7:0] char_in, input [5:0] s_length, input [5:0] t_length, input valid_in, output reg [7:0] char_out, output reg valid_out, output reg done); reg [7:0] s_buf [15:0]; reg [7:0] t_buf [15:0]; reg [5:0] zeros_s, ones_s, zeros_t, ones_t; reg [5:0] pi [15:0]; reg [5:0] overlap_len; reg [5:0] repeat_zeros, repeat_ones; reg [5:0] max_repeat; reg [15:0] total_output_length; reg [15:0] out_pos; reg [2:0] state; localparam IDLE = 3'd0; localparam INPUT_S = 3'd1; localparam INPUT_T = 3'd2; localparam COMPUTE_PREFIX = 3'd3; localparam FIND_OVERLAP = 3'd4; localparam ASSEMBLE_OUTPUT = 3'd5; localparam DONE = 3'd6; reg [5:0] s_count; reg [5:0] t_count; reg [5:0] i; always @(*) begin s_count <= 16'd0; t_count <= 16'd0; i <= 16'd0; out_pos <= 16'd0; total_output_length <= 16'd0; zeros_s <= 6'd0; ones_s <=6'd0; zeros_t <=6'd0; ones_t <=6'd0; pi <=16'd0; overlap_len <=6'd0; repeat_zeros <=6'd0; repeat_ones <=6'd0; max_repeat <=6'd0; state <= IDLE; s_buf <= 16'{8'h00}; t_buf <= 16'{8'h00}; end always @(posedge clk) begin if (!rst_n) begin s_count <=6'd0; t_count <=6'd0; i <=6'd0; out_pos <=16'd0; total_output_length <=16'd0; zeros_s <=6'd0; ones_s <=6'd0; zeros_t <=6'd0; ones_t <=6'd0; pi <=16'd0; overlap_len <=6'd0; repeat_zeros <=6'd0; repeat_ones <=6'd0; max_repeat <=6'd0; state <= IDLE; s_buf <= 16'{8'h00}; t_buf <= 16'{8'h00}; end else begin case (state) IDLE: begin if (start) begin s_count <= s_length; t_count <= t_length; i <=6'd0; out_pos <=16'd0; total_output_length <=16'd0; zeros_s <=6'd0; ones_s <=6'd0; zeros_t <=6'd0; ones_t <=6'd0; pi <=16'd0; overlap_len <=6'd0; repeat_zeros <=6'd0; repeat_ones <=6'd0; max_repeat <=6'd0; state <= INPUT_S; end valid_out <=1'b0; char_out <=8'h00; done <=1'b0; end INPUT_S: begin if (s_count < s_length) begin if (valid_in) begin s_buf[s_count] <= char_in; if (char_in == 8'h30) zeros_s <= zeros_s +1; else if (char_in ==8'h31) ones_s <= ones_s +1; s_count <= s_count +1; end end else begin state <= INPUT_T; end valid_out <=1'b0; char_out <=8'h00; done <=1'b0; end INPUT_T: begin if (t_count < t_length) begin if (valid_in) begin t_buf[t_count] <= char_in; if (char_in ==8'h30) zeros_t <= zeros_t +1; else if (char_in ==8'h31) ones_t <= ones_t +1; t_count <= t_count +1; end end else begin state <= COMPUTE_PREFIX; end valid_out <=1'b0; char_out <=8'h00; done <=1'b0; end COMPUTE_PREFIX: begin if (i < t_length) begin if (i ==0) begin pi[i] <=8'd0; i <= i +1; end else begin pi[i] <=8'd0; i <= i +1; end end else begin state <= FIND_OVERLAP; end valid_out <=1'b0; char_out <=8'h00; done <=1'b0; end FIND_OVERLAP: begin if (t_length ==0) begin total_output_length <=16'd0; state <= ASSEMBLE_OUTPUT; end else begin overlap_len <= pi[t_length-1]; max_repeat <=6'd0; total_output_length <= t_length; state <= ASSEMBLE_OUTPUT; end valid_out <=1'b0; char_out <=8'h00; done <=1'b0; end ASSEMBLE_OUTPUT: begin if (out_pos < total_output_length) begin if (out_pos < t_length) begin char_out <= t_buf[out_pos]; valid_out <=1'b1; end else begin char_out <= t_buf[out_pos % t_length]; valid_out <=1'b1; end out_pos <= out_pos +1; done <=1'b0; end else begin done <=1'b1; state <= DONE; end end DONE: begin valid_out <=1'b0; char_out <=8'h00; done <=1'b1; end endcase end end end assign done = done; assign valid_out = valid_out; assign char_out = char_out; endmodule